function bindMaterialActions(){document.querySelectorAll('[data-mf]').forEach(b=>b.onclick=()=>{state.materialFilter=b.dataset.mf;save();renderLearning()});document.querySelectorAll('[data-ma]').forEach(b=>b.onclick=()=>{const card=b.closest('[data-material-id]'),m=state.materials.find(x=>x.id===card.dataset.materialId);if(!m)return;if(b.dataset.ma==='view'){notify(`证据来源：${m.source} · 范围：${m.scope}`);return}snapshot('修改学习材料状态');if(b.dataset.ma==='approve')m.status='shadow';if(b.dataset.ma==='enable')m.status='enabled';if(b.dataset.ma==='rollback')m.status='shadow';log(`${m.title} 已进入${{shadow:'影子验证',enabled:'正式启用'}[m.status]||'回滚状态'}`);renderLearning()})}
function moneyLabel(value){return openRouterPresentationAuthority.formatMoney(value)}
function openRouterPolicySummary(){return openRouterPresentationAuthority.project(state.openRouter)}
function serviceCard(s){const c=s.capabilities||{};return `<article class="aiw30-service ${htmlAttr(s.verified?'verified':'')} ${htmlAttr(['failed','blocked'].includes(s.qualification)?'failed':'')}" data-service-id="${htmlAttr(s.id)}"><small>${htmlText(s.kind)} · ${htmlText(s.qualificationLabel)}</small><h4>${htmlText(s.name)}</h4><code>${htmlText(s.raw?.name||s.id)}</code><small>${htmlText(s.endpoint||'由 provider 适配器管理')}</small><div class="aiw30-service-tags">${(s.tags||[]).map(t=>`<span>${htmlText(t)}</span>`).join('')}</div>${s.technicalDetail?`<details class="aiw30-service-technical"><summary>技术详情</summary><code>${htmlText(s.technicalDetail)}</code></details>`:''}<footer><b>${htmlText(s.status)}</b><button data-service-test>Test / Probe</button><button data-service-lifecycle>${htmlText(s.userDisabled?'重新启用':'停用')}</button>${s.provider!=='ollama'?'<button data-service-edit>重新配置</button><button data-service-delete>删除配置与凭据</button>':''}</footer></article>`}
function modelRuntimeNotice(){const runtime=state.modelRuntime||defaults.modelRuntime,status=String(runtime.status||'idle'),brain=state.modelBrain||defaults.modelBrain;if(status==='loading')return {label:'正在同步',title:'正在读取 Model Brain 状态',detail:'正在读取 LiteLLM sealed runtime、模型目录与执行证据。'};if(status==='failed')return {label:'同步失败',title:'Model Brain 状态读取失败',detail:`${runtime.reasonCode||'MODEL_RUNTIME_STATUS_FAILED'} · ${runtime.lastError||'请打开系统诊断查看结构化错误证据。'}`};return {label:String(brain.health||'unavailable'),title:'Model Brain / LiteLLM',detail:`${brain.litellm||'LiteLLM v1.95.0'} · ${brain.complexityRouter||'ComplexityRouter'} · strict AND tags`}}
function evidenceCard(evidence={}){const selectedModel=evidence.selectedModel||'尚无执行证据',provider=evidence.provider||'—',latency=Number(evidence.latencyMs||0),tokens=Number(evidence.totalTokens||0),cost=Number(evidence.costUsd||0),retry=Number(evidence.retryCount||0),fallback=Number(evidence.fallbackCount||0);return `<div class="aiw30-governance"><article><b>selectedModel / provider</b><p>${htmlText(selectedModel)} · ${htmlText(provider)}</p></article><article><b>latency / tokens / cost</b><p>${htmlText(latency)} ms · ${htmlText(tokens)} tokens · ${htmlText(moneyLabel(cost))}</p></article><article><b>retry / fallback evidence</b><p>${htmlText(retry)} retries · ${htmlText(fallback)} LiteLLM fallbacks</p></article></div>`}
function renderModels(){const notice=modelRuntimeNotice(),brain=state.modelBrain||defaults.modelBrain,evidence=brain.lastEvidence||{},openRouter=openRouterPolicySummary(),local=state.services.filter(x=>x.sourceType==='local'),cloud=state.services.filter(x=>x.sourceType==='cloud'),qualified=state.services.filter(x=>x.verified&&!x.userDisabled);q('aiwModelsPanel').innerHTML=`<div class="aiw30-grid"><article class="aiw30-section wide"><header><h3>${htmlText(notice.title)}</h3><span>${htmlText(notice.label)}</span></header><p style="padding:0 12px 12px">${htmlText(notice.detail)}</p><div class="aiw30-governance"><article><b>LiteLLM authority</b><p>${htmlText(brain.litellm||'LiteLLM v1.95.0')} owns provider selection, retry, fallback, cooldown and runtime health.</p></article><article><b>ComplexityRouter</b><p>${htmlText(brain.complexityRouter||'ComplexityRouter')} · request complexity is classified by upstream LiteLLM, not a Yance score.</p></article><article><b>Hard eligibility</b><p>privacy · local / cloud · modality (vision / audio / video) · language · context · provider. Mandatory tags use AND semantics and fail closed.</p></article></div>${evidenceCard(evidence)}</article><article class="aiw30-section wide"><header><h3>模型来源与资格</h3><span>local ${htmlText(local.length)} · cloud ${htmlText(cloud.length)} · qualified ${htmlText(qualified.length)}</span></header><p style="padding:0 12px 12px">Yance 只登记 catalog / capability / qualification facts；physical provider/model 由 LiteLLM 在每次 logical Model Brain request 内决定。</p><div class="aiw30-service-grid">${state.services.length?state.services.slice().sort((a,b)=>String(a.name).localeCompare(String(b.name),'zh-CN')).map(serviceCard).join(''):'<div class="aiw30-contact-empty"><div><b>尚无模型目录</b><p>可 Scan local Ollama 或连接 OpenRouter。</p></div></div>'}</div></article><article class="aiw30-section wide"><header><h3>OpenRouter catalog / capability</h3><span>${htmlText(openRouter.connectionLabel)}</span></header><div class="aiw30-governance"><article><b>credential / account</b><p>${htmlText(openRouter.credentialConfigured?'credential configured':'not configured')} · ${htmlText(openRouter.account||'account managed in secure storage')}</p></article><article><b>catalog</b><p>${htmlText(openRouter.catalogLabel)}</p></article><article><b>logical smoke</b><p>${htmlText(openRouter.smokeLabel)}</p></article></div></article><article class="aiw30-section"><header><h3>可见能力</h3><span>硬资格，不是评分</span></header><div class="aiw30-governance"><article><b>privacy</b><p>local-only / cloud policy</p></article><article><b>modality</b><p>text · vision · audio · video</p></article><article><b>language / context</b><p>native-register / multilingual · context length</p></article><article><b>provider</b><p>explicit allow / deny only</p></article></div></article><article class="aiw30-section"><header><h3>运行状态</h3><span>${htmlText(brain.health||'unavailable')}</span></header><div class="aiw30-governance"><article><b>health</b><p>${htmlText(brain.runtimeAvailable?'sealed runtime available':'sealed runtime unavailable or degraded')}</p></article><article><b>tag filtering</b><p>${htmlText(brain.strictTagFiltering?'enabled':'disabled')} · match any = ${htmlText(String(brain.tagFilteringMatchAny===true))}</p></article></div></article></div>`;document.querySelectorAll('[data-service-test]').forEach(b=>b.onclick=()=>testModelService(b));document.querySelectorAll('[data-service-lifecycle]').forEach(b=>b.onclick=()=>toggleModelLifecycle(b));document.querySelectorAll('[data-service-edit]').forEach(b=>b.onclick=()=>{const card=b.closest('[data-service-id]'),service=state.services.find(x=>x.id===card?.dataset.serviceId);if(service)openCloudModelDialog(service)});document.querySelectorAll('[data-service-delete]').forEach(b=>b.onclick=()=>deleteCloudModel(b))}

async function toggleModelLifecycle(button){
  const card=button.closest('[data-service-id]'),service=state.services.find(x=>x.id===card?.dataset.serviceId);
  if(!service)return;
  const enabled=service.userDisabled===true;
  if(!enabled&&!await window.YanceDialogs.confirm({title:'停用模型',message:`停用 ${service.name}？它将退出 Model Brain 可用模型目录，不会删除本地模型文件。`,submitLabel:'停用'}))return;
  const old=button.textContent;button.disabled=true;button.textContent=enabled?'启用中…':'停用中…';
  try{await requestJson(`/api/r32/models/${encodeURIComponent(service.id)}/lifecycle`,{method:'PATCH',body:JSON.stringify({enabled,reason:'用户在AI工作台调整模型生命周期'})});await refreshAiRuntimeStatus();notify(enabled?'模型已重新启用，仍需通过硬资格后才能进入 Model Brain':'模型已停用并退出 Model Brain 可用目录','success')}catch(error){notify(error.message||'模型状态更新失败','error')}finally{button.disabled=false;button.textContent=old}
}


async function deleteLocalModel(button){
  const card=button.closest('[data-service-id]'),service=state.services.find(x=>x.id===card?.dataset.serviceId);
  if(!service||service.provider!=='ollama'||!service.userDisabled)return;
  const exact=await window.YanceDialogs.prompt({title:'永久删除本地模型',message:'这会从本机 Ollama 永久删除模型及其磁盘文件。',label:'输入完整模型名称确认',value:'',placeholder:service.raw?.name||service.name.replace('Ollama · ','')});
  const modelName=service.raw?.name||service.name.replace('Ollama · ','');
  if(exact!==modelName){if(exact!==null)notify('模型名称不一致，已取消删除','warning');return}
  const old=button.textContent;button.disabled=true;button.textContent='正在删除…';
  try{await requestJson(`/api/r32/models/local/${encodeURIComponent(service.id)}`,{method:'DELETE',body:JSON.stringify({confirmName:exact})});await refreshAiRuntimeStatus();notify('本地模型已从 Ollama 和言策注册表中删除','success')}catch(error){notify(error.message||'删除本地模型失败','error')}finally{button.disabled=false;button.textContent=old}
}
async function deleteCloudModel(button){
  const card=button.closest('[data-service-id]'),service=state.services.find(x=>x.id===card?.dataset.serviceId);
  if(!service||service.provider==='ollama')return;
  if(!await window.YanceDialogs.confirm({title:'删除云模型',message:`删除云模型 ${service.name}？该操作会删除模型配置和安全存储中的API密钥。`,danger:true,submitLabel:'删除'}))return;
  const old=button.textContent;button.disabled=true;button.textContent='删除中…';
  try{await requestJson(`/api/r32/models/cloud/${encodeURIComponent(service.id)}`,{method:'DELETE',body:JSON.stringify({removeCredential:true})});await refreshAiRuntimeStatus();notify('云模型配置和安全凭据已删除','success')}catch(error){notify(error.message||'删除云模型失败','error')}finally{button.disabled=false;button.textContent=old}
}

async function requestJson(url,options={}){const y=window.__Y27;if(y?.apiJson)return y.apiJson(url,options);const {timeoutMs,...fetchOptions}=options,response=await fetch(url,{headers:{Accept:'application/json','Content-Type':'application/json',...(fetchOptions.headers||{})},...fetchOptions});let payload;try{payload=await response.json()}catch(cause){const error=new Error('AI 工作台返回了无法解析的响应');error.code='AIW_INVALID_RESPONSE';error.status=response.status;error.cause=cause;throw error}if(!payload||typeof payload!=='object'){const error=new Error('AI 工作台返回了无效响应');error.code='AIW_INVALID_RESPONSE';error.status=response.status;throw error}if(!response.ok||payload.ok===false){if(window.YanceRuntimeErrors?.createError)throw window.YanceRuntimeErrors.createError(payload,{status:response.status,fallback:`HTTP ${response.status}`});const error=new Error(safeModelText(payload,`HTTP ${response.status}`));error.payload=payload;error.status=response.status;throw error}return payload}

function normalizeCloudApiKey(value=''){return String(value||'').trim().replace(/^Bearer\s+/i,'').trim()}
function wait(ms){return new Promise(resolve=>setTimeout(resolve,ms))}
function assertCredentialSave(result){if(!window.YanceCredentialMutationReceipt?.assertSaved){const error=new Error('凭据事务收据解释器未加载');error.code='CREDENTIAL_RECEIPT_AUTHORITY_UNAVAILABLE';throw error}return window.YanceCredentialMutationReceipt.assertSaved(result)}
async function waitForAiBackendAfterCredentialRestart(timeoutMs=60000){const started=Date.now();let lastError=null;while(Date.now()-started<timeoutMs){try{return await requestJson('/api/r32/models/status',{timeoutMs:10000})}catch(error){lastError=error;await wait(750)}}const error=new Error(lastError?.message||'安全存储更新后，AI 服务没有在规定时间内恢复');error.code='AI_BACKEND_RESTART_TIMEOUT';throw error}

function renderCloudModelOptions(models=[]){const rows=[...new Set((models||[]).map(value=>String(value||'').trim()).filter(Boolean))].sort();const list=q('aiwCloudModelOptions');if(list)list.innerHTML=rows.map(name=>`<option value="${htmlAttr(name)}"></option>`).join('');const status=q('aiwCloudDiscoveryStatus');if(status)status.textContent=rows.length?`当前 Key 可见 ${rows.length} 个模型：${rows.slice(0,8).join('、')}${rows.length>8?'…':''}`:'当前 Key 未返回可用模型';return rows}
async function autoConfigureOpenRouter(){
  const apiKey=normalizeCloudApiKey(q('aiwCloudKey').value);
  if(!apiKey){notify('请粘贴 OpenRouter API Key','warning');return}
  if(!window.yanceDesktop?.saveCredential){notify('系统安全存储不可用，不能保存 API Key','error');return}
  const button=q('aiwDialogSave'),old=button.textContent;
  button.disabled=true;
  let credentialSaved=false;
  try{
    const ref='model:openrouter:default',endpoint='https://openrouter.ai/api/v1';
    button.textContent='1/4 正在写入 Windows 安全存储…';
    const saved=await window.yanceDesktop.saveCredential(ref,{apiKey,endpoint,provider:'openai-compatible',service:'openrouter'});
    assertCredentialSave(saved);credentialSaved=true;q('aiwCloudKey').value='';
    button.textContent='2/4 正在等待 AI 服务恢复…';
    await waitForAiBackendAfterCredentialRestart();
    button.textContent='3/4 正在验证鉴权并读取真实模型目录…';
    const payload=await requestJson('/api/r32/models/cloud/openrouter/auto-configure',{method:'POST',body:JSON.stringify({credentialRef:ref,endpoint,smokeTimeoutMs:120000}),timeoutMs:360000});
    const snap=payload.snapshot||{};
    renderCloudModelOptions((snap.registered||[]).map(row=>row.id));
    button.textContent='4/4 Model Brain 逻辑烟测通过，正在同步完整模型快照…';
    const status=await requestJson('/api/r32/models/status');
    const modelSnapshot=projectModelRuntimeSnapshot(status,state);
    commitModelRuntimeSnapshot(modelSnapshot);
    snapshot('OpenRouter 鉴权、模型目录与 Model Brain 逻辑烟测');
    log(`OpenRouter 接入完成：目录 ${Number(payload.snapshot?.catalogCount||payload.snapshot?.modelCount||0)} 个模型；物理模型选择交由 LiteLLM。`);
    configureDialogMode('rule');q('aiwEditDialog').dataset.credentialRef='';q('aiwEditDialog').close();
    notify('OpenRouter 账号、目录与 Model Brain 逻辑烟测已同步。物理模型选择由 LiteLLM 管理。','success');
    renderPanel(state.tab);
  }catch(error){
    const payload=error.payload||{};
    const smokeRows=payload.onboarding?.results||payload.snapshot?.onboardingSmokeResults||[];
    const smokeDetail=smokeRows.length?`；逻辑烟测记录 ${smokeRows.length} 条`:'';
    const credentialCommitted=credentialSaved||error.mutationCommitted===true;const prefix=credentialCommitted?(error.runtimeConfirmed===false?'API Key 已安全保存，但运行时应用确认失败':'API Key 已安全保存，但接入没有完成'):'OpenRouter 自动配置失败';
    notify(`${prefix}：${error.message||'未知错误'}${smokeDetail}。未写入任何物理模型分配，可修正后重试。`,'error');
    log(`${prefix}：${error.code||''} ${error.message||''}${smokeDetail}`);
  }finally{button.disabled=false;button.textContent=old}
}

